declare(strict_types=1); require_once __DIR__ . '/../libs/DecisionEngine.php'; class SmartShading extends IPSModule { public function Create(): void { parent::Create(); $this->RegisterPropertyBoolean('Active', true); $this->RegisterPropertyBoolean('ShadowMode', true); $this->RegisterPropertyBoolean('AutoDiscoverLegacy', true); $this->RegisterPropertyInteger('EvaluationInterval', 300); $this->RegisterPropertyInteger('SunAzimuthID', 0); $this->RegisterPropertyInteger('SunElevationID', 0); $this->RegisterPropertyInteger('RadiationID', 0); $this->RegisterPropertyInteger('OutsideTemperatureID', 0); $this->RegisterPropertyInteger('WindAlarmID', 0); $this->RegisterPropertyInteger('RainAlarmID', 0); $this->RegisterPropertyFloat('SunOnThreshold', 300.0); $this->RegisterPropertyFloat('SunOffThreshold', 180.0); $this->RegisterPropertyString('Blinds', '[]'); $this->RegisterAttributeString('DecisionMemory', '{}'); $this->RegisterVariableString('Dashboard', $this->Translate('Dashboard'), '~HTMLBox'); $this->RegisterVariableString('StatusSummary', $this->Translate('Status Summary')); $this->RegisterVariableString('Inventory', $this->Translate('Inventory')); $this->RegisterVariableInteger('LastEvaluation', $this->Translate('Last Evaluation'), '~UnixTimestamp'); $this->RegisterTimer('EvaluateTimer', 0, 'SHD_Evaluate($_IPS["TARGET"]);'); } public function ApplyChanges(): void { parent::ApplyChanges(); $enabled = $this->ReadPropertyBoolean('Active'); $interval = max(30, $this->ReadPropertyInteger('EvaluationInterval')); $this->SetTimerInterval('EvaluateTimer', $enabled ? $interval * 1000 : 0); $this->SetStatus($enabled ? 102 : 104); if ($enabled) { $this->Evaluate(); } } public function GetConfigurationForm(): string { $configured = $this->readConfiguredBlinds(); $legacy = $this->discoverLegacyBlinds(); $values = []; foreach ($configured as $key => $blind) { $values[] = $this->toFormRow($blind, true, ''); } if ($this->ReadPropertyBoolean('AutoDiscoverLegacy')) { foreach ($legacy as $key => $blind) { if (isset($configured[(string)$key])) continue; $row = $this->toFormRow($blind, true, '#FFFFC0'); $row['source'] = 'legacy'; $values[] = $row; } } $form = [ 'elements' => [ [ 'type' => 'CheckBox', 'name' => 'Active', 'caption' => 'Active' ], [ 'type' => 'CheckBox', 'name' => 'ShadowMode', 'caption' => 'Shadow mode (no actuator writes)' ], [ 'type' => 'CheckBox', 'name' => 'AutoDiscoverLegacy', 'caption' => 'Discover legacy blind configurations automatically' ], [ 'type' => 'NumberSpinner', 'name' => 'EvaluationInterval', 'caption' => 'Evaluation interval (seconds)', 'minimum' => 30 ], [ 'type' => 'ExpansionPanel', 'caption' => 'Environment inputs', 'items' => [ $this->selectVariable('SunAzimuthID', 'Sun azimuth', [1,2]), $this->selectVariable('SunElevationID', 'Sun elevation', [1,2]), $this->selectVariable('RadiationID', 'Solar radiation', [1,2]), $this->selectVariable('OutsideTemperatureID', 'Outside temperature', [1,2]), $this->selectVariable('WindAlarmID', 'Wind alarm', [0]), $this->selectVariable('RainAlarmID', 'Rain/wetness alarm', [0]) ] ], [ 'type' => 'ExpansionPanel', 'caption' => 'Solar thresholds', 'items' => [ [ 'type' => 'NumberSpinner', 'name' => 'SunOnThreshold', 'caption' => 'Shade ON (W/m²)', 'digits' => 1 ], [ 'type' => 'NumberSpinner', 'name' => 'SunOffThreshold', 'caption' => 'Shade OFF (W/m²)', 'digits' => 1 ] ] ], [ 'type' => 'List', 'name' => 'Blinds', 'caption' => 'Blinds', 'add' => true, 'delete' => true, 'rowCount' => 12, 'values' => $values, 'columns' => $this->blindColumns(), 'form' => $this->blindEditForm() ] ], 'actions' => [ [ 'type' => 'Label', 'caption' => 'Yellow rows were discovered from the legacy installation and can be reviewed/saved into the module configuration.' ], [ 'type' => 'Button', 'caption' => 'Evaluate now', 'onClick' => 'SHD_Evaluate($id);' ], [ 'type' => 'Button', 'caption' => 'Show validation', 'onClick' => 'echo SHD_ValidateConfiguration($id);' ], [ 'type' => 'Button', 'caption' => 'Show inventory JSON', 'onClick' => 'echo SHD_GetInventoryJSON($id);' ] ], 'status' => [ ['code' => 102, 'icon' => 'active', 'caption' => 'Active'], ['code' => 104, 'icon' => 'inactive', 'caption' => 'Inactive'] ] ]; return json_encode($form, JSON_UNESCAPED_UNICODE); } public function Evaluate(): void { if (!$this->ReadPropertyBoolean('Active')) return; try { $blinds = $this->loadBlinds(); $memory = $this->readMemory(); $engine = new SHDEngine(); $decisions = []; $inventory = []; foreach ($blinds as $key => $blind) { if (!($blind['enabled'] ?? true)) continue; $state = $this->buildState($blind); $decision = $engine->decide($blind, $state, $memory[(string)$key] ?? []); $decisions[(string)$key] = [ 'name' => $blind['name'] ?? ('Blind ' . $key), 'decision' => $decision->toArray(), 'state' => $state, 'warnings' => $this->validateBlind($blind), 'shadowMode' => $this->ReadPropertyBoolean('ShadowMode') ]; $inventory[(string)$key] = $this->inventoryEntry($blind); $memory[(string)$key] = [ 'lastReasonCode' => $decision->reasonCode, 'lastPriority' => $decision->priority, 'lastTargetPosition' => $decision->position, 'lastTargetSlat' => $decision->slat, 'timestamp' => time() ]; } $this->WriteAttributeString('DecisionMemory', json_encode($memory, JSON_UNESCAPED_UNICODE)); $summary = [ 'timestamp' => time(), 'count' => count($decisions), 'shadowMode' => $this->ReadPropertyBoolean('ShadowMode'), 'decisions' => $decisions ]; SetValueString( $this->GetIDForIdent('StatusSummary'), json_encode($summary, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) ); SetValueString( $this->GetIDForIdent('Inventory'), json_encode($inventory, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) ); SetValueString($this->GetIDForIdent('Dashboard'), $this->renderDashboard($decisions)); SetValueInteger($this->GetIDForIdent('LastEvaluation'), time()); $this->SendDebug('Evaluate', count($decisions) . ' blinds evaluated. No actuator writes in v0.2.', 0); } catch (Throwable $e) { $this->SendDebug('EvaluateError', $e->getMessage(), 0); trigger_error('SmartShading: ' . $e->getMessage(), E_USER_WARNING); } } public function GetInventoryJSON(): string { $result = []; foreach ($this->loadBlinds() as $key => $blind) { $result[(string)$key] = $this->inventoryEntry($blind); } return json_encode($result, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE); } public function ValidateConfiguration(): string { $issues = []; foreach ([ 'SunAzimuthID' => 'Sun azimuth', 'SunElevationID' => 'Sun elevation', 'RadiationID' => 'Solar radiation', 'OutsideTemperatureID' => 'Outside temperature' ] as $property => $label) { if ($this->ReadPropertyInteger($property) <= 0) { $issues[] = $label . ' is not configured.'; } } $blinds = $this->loadBlinds(); foreach ($blinds as $key => $blind) { foreach ($this->validateBlind($blind) as $warning) { $issues[] = ($blind['name'] ?? $key) . ': ' . $warning; } } return json_encode([ 'blindCount' => count($blinds), 'issueCount' => count($issues), 'issues' => $issues ], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE); } private function readConfiguredBlinds(): array { $rows = json_decode($this->ReadPropertyString('Blinds'), true); if (!is_array($rows)) return []; $result = []; foreach ($rows as $index => $row) { if (!is_array($row)) continue; $blind = SHDConfig::normalizePublic($row); $key = $blind['blindID'] > 0 ? (string)$blind['blindID'] : 'configured_' . $index; $result[$key] = $blind; } return $result; } private function loadBlinds(): array { $configured = $this->readConfiguredBlinds(); if (!$this->ReadPropertyBoolean('AutoDiscoverLegacy')) return $configured; $legacy = $this->discoverLegacyBlinds(); foreach ($legacy as $key => $blind) { if (!isset($configured[(string)$key])) { $configured[(string)$key] = $blind; } } return $configured; } private function discoverLegacyBlinds(): array { $result = []; foreach (IPS_GetObjectList() as $id) { $object = IPS_GetObject($id); if (($object['ObjectType'] ?? -1) !== 2) continue; if (($object['ObjectName'] ?? '') !== 'Konfiguration') continue; $variable = IPS_GetVariable($id); if (($variable['VariableType'] ?? -1) !== 3) continue; $raw = json_decode(GetValueString($id), true); if (!is_array($raw)) continue; if (!array_key_exists('BehangID', $raw) && !array_key_exists('Typ', $raw)) continue; $blind = SHDConfig::normalizeLegacy($raw, $id); $blindID = $blind['blindID'] ?: IPS_GetParent($id); if ($blindID <= 0 || !IPS_ObjectExists($blindID)) { $blindID = IPS_GetParent($id); } $blind['blindID'] = $blindID; $blind['name'] = IPS_GetName($blindID); $this->autoMapExistingVariables($blind); $result[(string)$blindID] = $blind; } return $result; } private function autoMapExistingVariables(array &$blind): void { $name = mb_strtolower((string)($blind['name'] ?? '')); foreach (IPS_GetObjectList() as $id) { $object = IPS_GetObject($id); if (($object['ObjectType'] ?? -1) !== 2) continue; $candidate = mb_strtolower((string)($object['ObjectName'] ?? '')); if ($candidate === '') continue; $tokens = array_values(array_filter( preg_split('/\s+/u', preg_replace('/[^\pL\pN]+/u', ' ', $name) ?? ''), static fn($v) => mb_strlen($v) >= 4 )); $matchesName = false; foreach ($tokens as $token) { if (str_contains($candidate, $token)) { $matchesName = true; break; } } if (!$matchesName) continue; if (($blind['positionStatusID'] ?? 0) <= 0 && (str_contains($candidate, 'position') || str_contains($candidate, 'status')) && !str_contains($candidate, 'lamell')) { $blind['positionStatusID'] = $id; } if (($blind['slatStatusID'] ?? 0) <= 0 && str_contains($candidate, 'lamell') && (str_contains($candidate, 'pos') || str_contains($candidate, 'status'))) { $blind['slatStatusID'] = $id; } } } private function buildState(array $blind): array { $sunAzimuth = $this->readNumericVariable($this->ReadPropertyInteger('SunAzimuthID')); $sunElevation = $this->readNumericVariable($this->ReadPropertyInteger('SunElevationID')); $radiation = $this->readNumericVariable($this->ReadPropertyInteger('RadiationID')); $outside = $this->readNumericVariable($this->ReadPropertyInteger('OutsideTemperatureID')); $facade = SHDMath::facadeAzimuth($blind); $relative = ($sunAzimuth !== null && $facade !== null) ? SHDMath::signedAngle($sunAzimuth - $facade) : 0.0; $rain = $this->readBoolVariable($this->ReadPropertyInteger('RainAlarmID')) ?? false; return [ 'timestamp' => time(), 'sunAzimuth' => $sunAzimuth, 'sunElevation' => $sunElevation, 'relativeSunAzimuth' => $relative, 'directSun' => SHDMath::directSun($blind, $sunAzimuth, $sunElevation), 'radiation' => $radiation, 'radiationFiltered' => $radiation, 'outsideTemp' => $outside, 'roomTemp' => $this->readNumericVariable((int)($blind['roomTempID'] ?? 0)), 'roomSetpoint' => $this->readNumericVariable((int)($blind['roomSetpointID'] ?? 0)), 'roomTempTrendKPerH' => 0.0, 'windAlarm' => $this->readBoolVariable($this->ReadPropertyInteger('WindAlarmID')) ?? false, 'rainAlarm' => $rain, 'icingRisk' => $outside !== null && $outside <= 0.5 && $rain, 'doorOpen' => $this->readBoolVariable((int)($blind['doorContactID'] ?? 0)) ?? false, 'actualPosition' => $this->readNumericVariable((int)($blind['positionStatusID'] ?? 0)), 'actualSlat' => $this->readNumericVariable((int)($blind['slatStatusID'] ?? 0)), 'isNight' => $sunElevation !== null ? $sunElevation < -3.0 : ((int)date('G') < 6 || (int)date('G') >= 21), 'manualOverride' => null, 'sunOnThreshold' => $this->ReadPropertyFloat('SunOnThreshold'), 'sunOffThreshold' => $this->ReadPropertyFloat('SunOffThreshold') ]; } private function validateBlind(array $blind): array { $warnings = $blind['warnings'] ?? []; if (trim((string)($blind['name'] ?? '')) === '') $warnings[] = 'Name is empty.'; if (SHDMath::facadeAzimuth($blind) === null && (($blind['sunFrom'] ?? null) === null || ($blind['sunTo'] ?? null) === null)) { $warnings[] = 'No usable facade azimuth or sun window.'; } if ((int)($blind['roomTempID'] ?? 0) <= 0) $warnings[] = 'Room temperature missing.'; if ((int)($blind['roomSetpointID'] ?? 0) <= 0) $warnings[] = 'Room setpoint missing.'; if ((int)($blind['positionStatusID'] ?? 0) <= 0) $warnings[] = 'Position feedback missing.'; if (($blind['type'] ?? '') === 'venetian' && (int)($blind['slatStatusID'] ?? 0) <= 0) { $warnings[] = 'Slat feedback missing.'; } return array_values(array_unique($warnings)); } private function inventoryEntry(array $blind): array { return [ 'blindID' => $blind['blindID'] ?? 0, 'name' => $blind['name'] ?? '', 'source' => $blind['source'] ?? 'module', 'type' => $blind['type'] ?? '', 'room' => $blind['room'] ?? '', 'facadeAzimuth' => SHDMath::facadeAzimuth($blind), 'sunFrom' => $blind['sunFrom'] ?? null, 'sunTo' => $blind['sunTo'] ?? null, 'positionControlID' => $blind['positionControlID'] ?? 0, 'positionStatusID' => $blind['positionStatusID'] ?? 0, 'slatControlID' => $blind['slatControlID'] ?? 0, 'slatStatusID' => $blind['slatStatusID'] ?? 0, 'doorContactID' => $blind['doorContactID'] ?? 0, 'roomTempID' => $blind['roomTempID'] ?? 0, 'roomSetpointID' => $blind['roomSetpointID'] ?? 0, 'warnings' => $this->validateBlind($blind) ]; } private function renderDashboard(array $decisions): string { $rows = ''; foreach ($decisions as $entry) { $d = $entry['decision']; $s = $entry['state']; $warningCount = count($entry['warnings'] ?? []); $rows .= '<tr>' . '<td>' . htmlspecialchars((string)$entry['name']) . '</td>' . '<td>' . htmlspecialchars((string)$d['reasonCode']) . '</td>' . '<td style="text-align:right">' . (int)$d['priority'] . '</td>' . '<td style="text-align:right">' . $this->fmt($d['position'], '%') . '</td>' . '<td style="text-align:right">' . $this->fmt($d['slat'], '%') . '</td>' . '<td>' . (($s['directSun'] ?? false) ? '☀' : '–') . '</td>' . '<td style="text-align:right">' . $this->fmt($s['roomTemp'] ?? null, ' °C') . '</td>' . '<td style="text-align:right">' . $this->fmt($s['radiationFiltered'] ?? null, ' W/m²') . '</td>' . '<td style="text-align:center">' . ($warningCount > 0 ? '⚠ ' . $warningCount : '✓') . '</td>' . '</tr>'; } return '<div style="font-family:Arial,sans-serif">' . '<h3>SmartShading — Shadow diagnostics</h3>' . '<div>Mode: <b>' . ($this->ReadPropertyBoolean('ShadowMode') ? 'SHADOW' : 'CONTROL (driver not implemented)') . '</b>' . ' · Updated: ' . date('Y-m-d H:i:s') . '</div>' . '<table style="border-collapse:collapse;width:100%;margin-top:8px">' . '<thead><tr>' . '<th style="text-align:left">Blind</th><th style="text-align:left">Decision</th>' . '<th>Prio</th><th>Pos.</th><th>Slat</th><th>Sun</th>' . '<th>Room</th><th>Radiation</th><th>Config</th>' . '</tr></thead><tbody>' . $rows . '</tbody></table></div>'; } private function fmt(mixed $value, string $suffix): string { if ($value === null) return '–'; return number_format((float)$value, 1, ',', '.') . $suffix; } private function blindColumns(): array { return [ ['name' => 'enabled', 'caption' => 'On', 'width' => '50px', 'add' => true, 'edit' => ['type' => 'CheckBox']], ['name' => 'name', 'caption' => 'Name', 'width' => 'auto', 'add' => '', 'edit' => ['type' => 'ValidationTextBox']], ['name' => 'room', 'caption' => 'Room', 'width' => '120px', 'add' => '', 'edit' => ['type' => 'ValidationTextBox']], ['name' => 'type', 'caption' => 'Type', 'width' => '95px', 'add' => 'venetian', 'edit' => [ 'type' => 'Select', 'options' => [ ['caption' => 'Venetian', 'value' => 'venetian'], ['caption' => 'Roller', 'value' => 'roller'] ] ]], ['name' => 'facadeAzimuth', 'caption' => 'Azimuth', 'width' => '80px', 'add' => 0, 'edit' => ['type' => 'NumberSpinner', 'minimum' => 0, 'maximum' => 359]], ['name' => 'positionStatusID', 'caption' => 'Pos status', 'width' => '95px', 'add' => 0, 'edit' => ['type' => 'SelectVariable', 'validVariableTypes' => [1,2]]], ['name' => 'slatStatusID', 'caption' => 'Slat status', 'width' => '95px', 'add' => 0, 'edit' => ['type' => 'SelectVariable', 'validVariableTypes' => [1,2]]], ['name' => 'source', 'caption' => 'Source', 'width' => '75px', 'add' => 'module', 'save' => true] ]; } private function blindEditForm(): array { return [ [ 'type' => 'CheckBox', 'name' => 'enabled', 'caption' => 'Enabled' ], [ 'type' => 'ValidationTextBox', 'name' => 'name', 'caption' => 'Name' ], [ 'type' => 'ValidationTextBox', 'name' => 'room', 'caption' => 'Room' ], [ 'type' => 'Select', 'name' => 'type', 'caption' => 'Blind type', 'options' => [ ['caption' => 'Venetian blind', 'value' => 'venetian'], ['caption' => 'Roller shutter', 'value' => 'roller'] ] ], [ 'type' => 'NumberSpinner', 'name' => 'facadeAzimuth', 'caption' => 'Facade azimuth (0=N, 90=E, 180=S, 270=W)', 'minimum' => 0, 'maximum' => 359 ], [ 'type' => 'RowLayout', 'items' => [ ['type' => 'NumberSpinner', 'name' => 'sunFrom', 'caption' => 'Sun from', 'minimum' => 0, 'maximum' => 359], ['type' => 'NumberSpinner', 'name' => 'sunTo', 'caption' => 'Sun to', 'minimum' => 0, 'maximum' => 359] ] ], [ 'type' => 'ExpansionPanel', 'caption' => 'Actuator and feedback', 'items' => [ $this->selectVariable('positionControlID', 'Position control', [1,2], 1), $this->selectVariable('positionStatusID', 'Position feedback', [1,2]), $this->selectVariable('slatControlID', 'Slat control', [1,2], 1), $this->selectVariable('slatStatusID', 'Slat feedback', [1,2]) ] ], [ 'type' => 'ExpansionPanel', 'caption' => 'Room and door', 'items' => [ $this->selectVariable('roomTempID', 'Room temperature', [1,2]), $this->selectVariable('roomSetpointID', 'Room setpoint', [1,2]), $this->selectVariable('doorContactID', 'Door contact', [0]) ] ], [ 'type' => 'ExpansionPanel', 'caption' => 'Privacy', 'items' => [ ['type' => 'NumberSpinner', 'name' => 'privacyDayPosition', 'caption' => 'Day position %', 'minimum' => 0, 'maximum' => 100], ['type' => 'NumberSpinner', 'name' => 'privacyDaySlat', 'caption' => 'Day slat %', 'minimum' => 0, 'maximum' => 100], ['type' => 'NumberSpinner', 'name' => 'privacyNightPosition', 'caption' => 'Night position %', 'minimum' => 0, 'maximum' => 100], ['type' => 'NumberSpinner', 'name' => 'privacyNightSlat', 'caption' => 'Night slat %', 'minimum' => 0, 'maximum' => 100] ] ], ['type' => 'NumberSpinner', 'name' => 'blindID', 'caption' => 'Legacy blind ID', 'visible' => false], ['type' => 'NumberSpinner', 'name' => 'configVariableID', 'caption' => 'Legacy config variable ID', 'visible' => false], ['type' => 'ValidationTextBox', 'name' => 'source', 'caption' => 'Source', 'visible' => false] ]; } private function toFormRow(array $blind, bool $editable, string $rowColor): array { return array_merge($blind, [ 'editable' => $editable, 'rowColor' => $rowColor, 'source' => $blind['source'] ?? 'module' ]); } private function selectVariable( string $name, string $caption, array $types, int $requiredAction = 0 ): array { return [ 'type' => 'SelectVariable', 'name' => $name, 'caption' => $caption, 'validVariableTypes' => $types, 'requiredAction' => $requiredAction ]; } private function readNumericVariable(int $id): ?float { if ($id <= 0 || !IPS_VariableExists($id)) return null; $value = GetValue($id); return is_numeric($value) ? (float)$value : null; } private function readBoolVariable(int $id): ?bool { if ($id <= 0 || !IPS_VariableExists($id)) return null; return (bool)GetValue($id); } private function readMemory(): array { $data = json_decode($this->ReadAttributeString('DecisionMemory'), true); return is_array($data) ? $data : []; } }
